window.EXTRA_QUESTIONS = [
  [1,'Khi đánh giá chất lượng của một chiếc ghế làm việc, điều nào cần xem xét cùng với vẻ ngoài?',['Mức độ phù hợp khi sử dụng, độ an toàn và độ bền','Chỉ giá bán cao hay thấp','Chỉ màu sơn','Chỉ số lượng quảng cáo'],0,'Mục 1: Chất lượng được đánh giá theo mục đích sử dụng và nhiều yêu cầu liên quan, không chỉ hình thức.','作業用の椅子の品質を評価するとき、見た目とともに確認すべきことは何ですか。',['使用目的への適合、安全性、耐久性','価格の高さだけ','塗装の色だけ','広告の量だけ'],'第1項：品質は外観だけでなく、使用目的や関連する要求から評価します。'],
  [2,'“Market-in” bắt đầu từ đâu khi thiết kế sản phẩm?',['Năng lực máy móc sẵn có','Nhu cầu và cách sử dụng của khách hàng','Ý thích riêng của người quản lý','Mẫu sản phẩm cũ'],1,'Mục 2: Market-in lấy nhu cầu thị trường và khách hàng làm điểm xuất phát.','製品設計における「マーケットイン」の出発点は何ですか。',['既存設備の能力','顧客のニーズと使い方','管理者個人の好み','従来製品の形'],'第2項：マーケットインは市場と顧客のニーズを出発点にします。'],
  [2,'Một lỗi nhỏ lặp lại khiến phải làm lại nhiều sản phẩm. Nhận định nào đúng?',['Chỉ tính số sản phẩm bỏ đi','Tổn thất còn gồm thời gian, chi phí và nguy cơ mất lòng tin','Không cần xử lý nếu kịp giao hàng','Tăng kiểm tra cuối là đủ trong mọi trường hợp'],1,'Mục 2: Chất lượng kém gây lãng phí và ảnh hưởng cả chi phí, tiến độ lẫn lòng tin.','小さな不良が繰り返され、多くの製品で手直しが発生しました。適切な考え方はどれですか。',['廃棄品の数だけを数える','時間・費用・信頼への影響も考える','納期に間に合えば対処しない','最終検査を増やせば必ず十分'],'第2項：品質不良は手直しの費用や時間、顧客の信頼にも影響します。'],
  [3,'Cùng một công việc nhưng kết quả khác nhau tùy người làm. Nên ưu tiên điều gì?',['Chỉ chọn người có kinh nghiệm nhất','Làm rõ cách làm và kiểm soát biến động của quá trình','Bỏ tiêu chuẩn để linh hoạt','Chỉ sửa sản phẩm sau kiểm tra'],1,'Mục 3: Quản lý chất lượng cần tạo ra quá trình ổn định, không phụ thuộc hoàn toàn vào một cá nhân.','担当者によって同じ作業の結果がばらつきます。優先すべきことは何ですか。',['熟練者だけに任せる','作業方法を明確にし、工程のばらつきを管理する','標準をなくす','検査後に製品だけを直す'],'第3項：品質管理では、特定の人だけに頼らず安定した工程をつくります。'],
  [4,'Khách hàng ít khi gửi khiếu nại nhưng tỏ ra khó dùng sản phẩm. Nguồn thông tin nào hữu ích?',['Chỉ số lượng khiếu nại chính thức','Quan sát cách sử dụng và thu thập ý kiến trực tiếp','Chỉ báo cáo nội bộ','Chỉ giá của đối thủ'],1,'Mục 4: Nhu cầu khách hàng có thể được hiểu qua quan sát và phản hồi, không chỉ qua khiếu nại.','苦情は少ないものの、顧客は製品を使いにくそうにしています。有効な情報源はどれですか。',['正式な苦情件数だけ','使用状況の観察と顧客の声','社内報告だけ','競合品の価格だけ'],'第4項：顧客の期待は苦情だけでなく、観察や声からも把握します。'],
  [4,'“Dễ mở” là mong muốn của khách hàng đối với bao bì. Cách đặt chất lượng mục tiêu phù hợp là gì?',['Giữ nguyên cụm từ mơ hồ','Xác định điều kiện sử dụng và tiêu chí đánh giá mức độ dễ mở','Để mỗi nhân viên tự hiểu','Chỉ ghi màu bao bì'],1,'Mục 4: Mong đợi của khách hàng cần chuyển thành mục tiêu đủ rõ để đánh giá.','包装を「開けやすく」という顧客の希望があります。適切な品質目標の決め方はどれですか。',['曖昧な言葉のままにする','使用条件と開けやすさの評価基準を決める','担当者ごとの解釈に任せる','包装の色だけを決める'],'第4項：顧客の期待を評価可能な目標に具体化します。'],
  [5,'Tỷ lệ lỗi đã đạt mục tiêu cũ, nhưng nhóm muốn giảm thêm để vượt kỳ vọng khách hàng. Đây là gì?',['Một mục tiêu thách thức để nâng mức hiện tại','Một khiếu nại','Một kiểm tra lấy mẫu','Một bất thường đột xuất'],0,'Mục 5: Mục tiêu thách thức hướng đến mức tốt hơn ngay cả khi đã đạt chuẩn hiện tại.','不良率は従来の目標を達成しましたが、顧客の期待を超えるためさらに下げたいと考えています。これは何ですか。',['現在より高い水準を目指す課題','苦情','抜取検査','突発的な異常'],'第5項：課題は現状の基準を満たした後も、より高い水準を目指します。'],
  [6,'Không có khiếu nại nào được gửi đến. Có thể kết luận mọi khách hàng đều hài lòng không?',['Có, vì mọi bất mãn đều thành khiếu nại','Không; cần chủ động tìm hiểu cả ý kiến chưa được nói ra','Có, nếu hàng đã giao đủ','Có, nếu bộ phận QC đồng ý'],1,'Mục 6: Nhiều khách hàng không khiếu nại dù có điều chưa hài lòng.','苦情が届いていません。全顧客が満足していると判断できますか。',['できる。不満は必ず苦情になる','できない。表明されない不満も把握する必要がある','納品数が合えば判断できる','品質部門が同意すれば判断できる'],'第6項：苦情がないことは、必ずしも不満がないことを意味しません。'],
  [6,'Khách hàng phàn nàn việc trả lời chậm dù sản phẩm đạt thông số. Cách nhìn phù hợp là gì?',['Bỏ qua vì sản phẩm không lỗi','Xem cả chất lượng phục vụ và quy trình phản hồi','Chỉ kiểm tra lại kích thước sản phẩm','Yêu cầu khách hàng không liên hệ nữa'],1,'Mục 6: Phàn nàn có thể liên quan đến dịch vụ và cách làm việc, không chỉ bản thân sản phẩm.','製品は仕様どおりですが、返答が遅いと顧客から指摘されました。適切な対応はどれですか。',['製品に不良がないので無視する','対応サービスと返答の工程も確認する','製品の寸法だけを再測定する','顧客に連絡をやめてもらう'],'第6項：苦情は製品だけでなく、対応やサービスの品質にも関係します。'],
  [8,'Một hướng dẫn chỉ ghi “làm cẩn thận”. Cần bổ sung gì để dễ thực hiện thống nhất?',['Tiêu chí hoàn thành và các bước kiểm tra cụ thể','Tên tác giả của hướng dẫn','Khẩu hiệu dài hơn','Màu giấy khác'],0,'Mục 8: Công việc cần có trình tự và tiêu chí xác nhận rõ ràng.','作業手順書に「注意して作業する」とだけあります。統一して実施するために何を加えますか。',['具体的な手順と完了の確認基準','手順書の著者名','より長い標語','紙の色'],'第8項：作業には具体的な手順と確認基準が必要です。'],
  [8,'Kế hoạch triển khai công việc nên chỉ rõ điều gì?',['Ai làm, việc gì, khi nào và bằng cách nào','Chỉ ngày hoàn thành','Chỉ tên người quản lý','Chỉ mục tiêu doanh thu'],0,'Mục 8: Làm rõ các yếu tố như người phụ trách, thời điểm và phương pháp giúp công việc được thực hiện và kiểm tra.','仕事の実施計画で明確にすべき内容はどれですか。',['誰が、何を、いつ、どのように行うか','完了日だけ','管理者の名前だけ','売上目標だけ'],'第8項：担当者、内容、時期、方法を明確にすると実行と確認がしやすくなります。'],
  [9,'Trong PDCA, bước Check là gì?',['Lập mục tiêu mới mà không xem kết quả','So sánh kết quả thực tế với kế hoạch và tìm lý do chênh lệch','Chỉ thực hiện công việc','Chuẩn hóa ngay mọi thay đổi'],1,'Mục 9: Check xác nhận kết quả so với kế hoạch để quyết định điều chỉnh phù hợp.','PDCAの「Check」は何を行いますか。',['結果を見ずに新しい目標を立てる','実績と計画を比較し、差の理由を調べる','作業を行うだけ','すべての変更を直ちに標準化する'],'第9項：Checkでは実績を計画と照らし合わせ、差を確認します。'],
  [10,'Nhóm theo dõi tỷ lệ hàng lỗi và nhiệt độ máy. Cặp nào đúng?',['Cả hai đều chỉ là kết quả','Tỷ lệ hàng lỗi là kết quả; nhiệt độ máy là yếu tố quá trình','Nhiệt độ máy là kết quả; tỷ lệ lỗi là yếu tố quá trình','Cả hai đều không liên quan chất lượng'],1,'Mục 10: Chỉ tiêu kết quả cho biết đầu ra; chỉ tiêu yếu tố giúp quản lý điều kiện tạo ra đầu ra.','不良率と設備温度を監視しています。正しい組合せはどれですか。',['両方とも結果の指標','不良率は結果、設備温度は工程要因の指標','設備温度は結果、不良率は工程要因の指標','両方とも品質に無関係'],'第10項：結果の指標と、結果に影響する要因の指標を区別します。'],
  [10,'Khi đặt một hạng mục quản lý, ngoài tên chỉ tiêu còn cần gì?',['Mục tiêu, cách đo và tần suất kiểm tra','Chỉ biểu tượng đẹp','Chỉ tên người viết báo cáo','Chỉ số liệu của năm trước'],0,'Mục 10: Chỉ tiêu hữu ích khi có mức cần đạt và phương pháp theo dõi rõ ràng.','管理項目を設定するとき、指標名以外に必要なのは何ですか。',['目標値、測定方法、確認頻度','見栄えのよい記号だけ','報告書の作成者名だけ','前年の数値だけ'],'第10項：目標と測定・確認方法を明確にすると管理に役立ちます。'],
  [11,'Sau khi thay đổi thao tác và thấy lỗi giảm trong một ngày, nên làm gì trước khi áp dụng rộng?',['Xác nhận hiệu quả qua dữ liệu và điều kiện khác nhau','Công bố chắc chắn thành công','Xóa số liệu cũ','Dừng theo dõi'],0,'Mục 11: Cải tiến cần kiểm chứng hiệu quả trước khi duy trì và mở rộng.','作業方法を変えた翌日、不良が減りました。広く適用する前に何をしますか。',['データや条件を変えて効果を確認する','成功が確実だと発表する','以前のデータを消す','監視をやめる'],'第11項：改善の効果を確認してから定着・展開します。'],
  [12,'Trong QC Story, nên chọn chủ đề cải tiến dựa trên gì?',['Mức độ ảnh hưởng và dữ liệu thực tế','Chỉ chủ đề dễ trình bày','Chỉ ý kiến người nói to nhất','Chủ đề chưa có số liệu nhưng nghe hấp dẫn'],0,'Mục 12: Chọn chủ đề dựa trên vấn đề thực tế và mức độ cần ưu tiên.','QCストーリーの改善テーマは何に基づいて選びますか。',['影響の大きさと実際のデータ','発表しやすさだけ','声の大きい人の意見だけ','魅力的に聞こえる題名だけ'],'第12項：実態と影響を確認して改善テーマを選びます。'],
  [12,'Đối sách đã thực hiện nhưng mục tiêu chưa đạt. Bước phù hợp là gì?',['Xem lại dữ liệu, phân tích nguyên nhân và điều chỉnh đối sách','Tuyên bố hoàn thành','Đổi cách tính để đạt mục tiêu','Bỏ theo dõi'],0,'Mục 12: QC Story cần kiểm tra hiệu quả và quay lại phân tích nếu chưa đạt.','対策を実施しましたが目標に届きません。適切な次の行動は何ですか。',['データと原因分析を見直し、対策を修正する','完了したことにする','計算方法を変えて達成扱いにする','確認をやめる'],'第12項：効果が足りなければ原因や対策を見直します。'],
  [13,'Sản phẩm làm sai phải tháo ra rồi làm lại dù vẫn có thể bán. Đây chủ yếu là gì?',['Muda vì phát sinh thao tác không tạo giá trị','Muri vì chỉ có máy móc','Mura vì chỉ có khách hàng','Không phải tổn thất'],0,'Mục 13: Làm lại tiêu tốn thời gian và nguồn lực mà không thêm giá trị cho khách hàng.','製品を作り直して販売できましたが、分解と再作業が必要でした。主に何に当たりますか。',['価値を生まない再作業によるムダ','機械だけによるムリ','顧客だけによるムラ','損失ではない'],'第13項：手直しは顧客価値を増やさず、時間や資源を使うムダです。'],
  [14,'Hoạt động QC Circle hiệu quả thường có đặc điểm nào?',['Nhóm nhỏ cùng quan sát vấn đề và cải tiến công việc','Chỉ ban quản lý quyết định mọi ý tưởng','Chỉ họp khi có kiểm toán','Không chia sẻ kết quả'],0,'Mục 14: Nhóm nhỏ chủ động học hỏi và giải quyết vấn đề tại nơi làm việc.','QCサークル活動の特徴として適切なのはどれですか。',['小集団で問題を見つけ、仕事を改善する','管理者だけが全案を決める','監査時だけ集まる','結果を共有しない'],'第14項：小集団で主体的に学び、職場の課題を改善します。'],
  [15,'Có nhiều vấn đề nhưng nguồn lực có hạn. Cách chọn trọng điểm là gì?',['Ưu tiên vấn đề có ảnh hưởng lớn dựa trên dữ liệu','Làm việc dễ nhất trước trong mọi trường hợp','Chia đều thời gian cho tất cả','Chỉ chọn vấn đề mới nhất'],0,'Mục 15: Định hướng trọng điểm tập trung nguồn lực vào vấn đề quan trọng.','問題が多く、資源は限られています。重点をどう選びますか。',['データを基に影響の大きい問題を優先する','常に最も簡単な仕事を先にする','すべてに同じ時間を配分する','最も新しい問題だけを選ぶ'],'第15項：重点指向では重要な問題へ資源を集中します。'],
  [16,'Công đoạn sau nhận linh kiện thiếu thông tin về lô. Công đoạn trước nên làm gì?',['Bàn giao đủ thông tin để công đoạn sau sử dụng và truy vết','Để công đoạn sau tự đoán','Chỉ gửi số lượng','Bỏ qua vì linh kiện trông tốt'],0,'Mục 16: Công đoạn trước cần đáp ứng yêu cầu của công đoạn sau, gồm cả thông tin cần thiết.','後工程に渡した部品にロット情報がありません。前工程はどうすべきですか。',['後工程が使い追跡できる情報を添えて渡す','後工程に推測させる','数量だけ伝える','見た目がよければ無視する'],'第16項：前工程は後工程に必要な品質と情報を渡します。'],
  [16,'Vì sao công đoạn sau được xem là “khách hàng” của công đoạn trước?',['Vì đầu ra của công đoạn trước phải phù hợp để công đoạn sau làm việc','Vì công đoạn sau luôn trả tiền','Vì công đoạn trước không chịu trách nhiệm','Vì chỉ công đoạn cuối mới kiểm tra'],0,'Mục 16: Mỗi công đoạn cần giao đầu ra đáp ứng nhu cầu của công đoạn kế tiếp.','後工程を前工程の「お客様」と考える理由は何ですか。',['前工程の成果が後工程の作業に適合する必要があるから','後工程が必ず代金を払うから','前工程には責任がないから','最終工程だけが検査するから'],'第16項：次の工程が必要とする状態で成果を渡します。'],
  [17,'Trong 5M của công đoạn, đồng hồ đo bị sai lệch thuộc yếu tố nào?',['Measurement (đo lường)','Man (con người)','Material (nguyên vật liệu)','Method (phương pháp)'],0,'Mục 17: Thiết bị và phương pháp đo có thể ảnh hưởng đến dữ liệu dùng để quản lý quá trình.','工程の5Mで、計測器のずれはどの要素に当たりますか。',['Measurement（測定）','Man（人）','Material（材料）','Method（方法）'],'第17項：計測器の状態は測定に関わる要素です。'],
  [17,'Chất lượng bỗng biến động sau khi thay vật liệu. Cách xem xét 5M phù hợp là gì?',['Kiểm tra thay đổi của vật liệu và các điều kiện liên quan','Quy lỗi ngay cho người vận hành','Bỏ qua vì máy không đổi','Chỉ tăng tốc độ sản xuất'],0,'Mục 17: Khi kết quả thay đổi, xem xét các yếu tố 5M và thay đổi đã xảy ra.','材料を変更した後、品質が急にばらつきました。5Mに沿った確認はどれですか。',['材料と関連する条件の変化を調べる','すぐに作業者の責任にする','設備が同じなら無視する','生産速度だけ上げる'],'第17項：結果が変わったときは、5Mの変化を確認します。'],
  [18,'Giá trị đo đột ngột lệch xa mức thường thấy. Nên làm gì?',['Xác minh phép đo và tìm nguyên nhân đặc biệt','Tự động xóa giá trị','Chờ hết ca mới báo','Giả định mọi biến động đều ngẫu nhiên'],0,'Mục 18: Dấu hiệu khác thường cần được xác minh và tìm nguyên nhân để tránh hậu quả lan rộng.','測定値が突然いつもの範囲から大きく外れました。どうしますか。',['測定を確かめ、特別な原因を調べる','値を自動的に消す','終業まで報告しない','すべて偶然の変動と決めつける'],'第18項：異常な兆候は早く確認し、原因を調べます。'],
  [18,'Một tiếng động lạ xuất hiện ở máy dù thành phẩm hiện vẫn đạt. Cách ứng xử là gì?',['Báo và kiểm tra sớm để xác định bất thường','Chỉ xử lý khi có phế phẩm','Che tiếng động bằng nhạc','Tăng tốc máy để bù tiến độ'],0,'Mục 18: Bất thường của quá trình cần được nhận biết sớm, trước khi biến thành lỗi sản phẩm.','製品はまだ合格ですが、設備から異音がします。どう対応しますか。',['早く報告・点検して異常を確認する','不良品が出るまで待つ','音楽で異音を隠す','納期のため設備を速くする'],'第18項：製品不良になる前に工程の異常を捉えます。'],
  [19,'Đo chiều dài được 10,4 mm; giới hạn cho phép là 10,0 ± 0,2 mm. “Kiểm tra” còn cần làm gì?',['So sánh với giới hạn và kết luận đạt hay không','Chỉ ghi 10,4 mm','Đổi đơn vị rồi bỏ qua','Chỉ hỏi người vận hành'],0,'Mục 19: Đo tạo dữ liệu; kiểm tra còn đối chiếu yêu cầu để phán định.','長さを測ると10.4 mmで、許容範囲は10.0±0.2 mmでした。検査ではさらに何をしますか。',['許容範囲と比較して合否を判断する','10.4 mmと記録するだけ','単位を変えて無視する','作業者に聞くだけ'],'第19項：測定値を要求と比較し、合否を判断します。'],
  [19,'Kiểm tra phát hiện nhiều lỗi cùng một vị trí. Thông tin đó nên được sử dụng thế nào?',['Phản hồi cho công đoạn để tìm và giảm nguyên nhân','Chỉ cất vào kho lưu trữ','Chỉ loại bỏ sản phẩm lỗi','Không chia sẻ vì đã có kết quả'],0,'Mục 19: Kết quả kiểm tra giúp phát hiện và cải thiện nguyên nhân tại quá trình.','検査で同じ箇所の不良が多く見つかりました。結果をどう活用しますか。',['工程へ戻して原因を調べ、減らす','記録を保管するだけ','不良品を除くだけ','結果が出たので共有しない'],'第19項：検査結果を工程改善にも役立てます。'],
  [21,'Sản phẩm hoạt động bình thường nhưng kích thước vượt dung sai quy định. Nhận định nào đúng?',['Là sản phẩm không phù hợp yêu cầu','Luôn là sản phẩm phù hợp vì vẫn chạy','Chỉ là bất thường của giấy tờ','Không cần ghi nhận'],0,'Mục 21: Vượt yêu cầu quy định là không phù hợp, dù bề ngoài hoặc chức năng trước mắt có vẻ bình thường.','製品は動作しますが、寸法が規定公差を超えています。正しい判断はどれですか。',['要求に適合しない製品である','動くので必ず適合品である','書類上だけの異常である','記録は不要である'],'第21項：規定を満たさなければ、見た目や当面の動作がよくても不適合です。'],
  [21,'Phát hiện một thùng hàng nghi không phù hợp giữa kho thành phẩm. Việc đầu tiên cần làm là gì?',['Nhận diện và cách ly để tránh giao nhầm','Giao ngay cho khách','Trộn với hàng đạt','Xóa mã lô'],0,'Mục 21: Hàng nghi không phù hợp cần được kiểm soát để tránh lọt sang công đoạn sau hoặc khách hàng.','完成品倉庫で不適合が疑われる箱を見つけました。まず何をしますか。',['識別・隔離して誤出荷を防ぐ','すぐ出荷する','合格品と混ぜる','ロット番号を消す'],'第21項：疑わしい品を識別・管理し、流出を防ぎます。'],
  [22,'Một lô được chấp nhận theo kết quả lấy mẫu. Có thể khẳng định từng sản phẩm đều đạt không?',['Có, lấy mẫu bảo đảm tuyệt đối','Không; kết luận về lô không đồng nghĩa đã kiểm từng sản phẩm','Có, nếu lô có nhãn xanh','Có, nếu nhân viên có kinh nghiệm'],1,'Mục 22: Phán định lô theo mẫu và phán định từng sản phẩm là hai phạm vi khác nhau.','抜取結果からロットを合格としました。全品が合格だと断言できますか。',['できる。抜取なら絶対に保証される','できない。ロット判定と全品検査は異なる','緑色のラベルがあればできる','熟練者ならできる'],'第22項：ロットの合否と個々の製品の合否は区別します。'],
  [22,'Trong kiểm tra theo lô, “lô” là gì?',['Một nhóm sản phẩm được xác định để cùng phán định','Bất kỳ một sản phẩm đơn lẻ','Chỉ kho chứa hàng','Tên của thiết bị đo'],0,'Mục 22: Cần xác định nhóm sản phẩm được xét chung trước khi quyết định đạt/không đạt của lô.','ロットの検査で「ロット」とは何ですか。',['まとめて判定するために定めた製品の集まり','任意の製品1個','保管倉庫だけ','測定器の名称'],'第22項：ロットはまとめて合否を判定する対象の集まりです。'],
  [23,'Thử độ bền làm mẫu bị phá hủy. Cách kiểm tra nào thường phù hợp hơn khi không thể thử mọi sản phẩm?',['Lấy mẫu theo kế hoạch phù hợp','Kiểm tra phá hủy toàn bộ hàng bán','Không kiểm tra gì','Chỉ nhìn màu sản phẩm'],0,'Mục 23: Kiểm tra phá hủy thường cần chọn mẫu phù hợp vì mẫu không thể tiếp tục sử dụng.','強度試験で製品が壊れます。全品を試せないとき、一般に適する方法はどれですか。',['適切な計画に基づく抜取検査','販売品の全数を破壊検査する','一切検査しない','色だけ見る'],'第23項：破壊検査では、目的に合う抜取方法を検討します。'],
  [23,'Một phép đo không làm hỏng sản phẩm và cần kiểm tra mọi đơn vị vì rủi ro bỏ sót cao. Lựa chọn nào phù hợp?',['Kiểm tra toàn bộ theo tiêu chí đã định','Chỉ kiểm một sản phẩm bất kỳ','Không cần tiêu chí','Thay bằng lời cam kết'],0,'Mục 23: Phương pháp kiểm tra phụ thuộc mục đích, rủi ro và tính chất phép thử.','製品を壊さず測定でき、見逃しの危険が高いため全品確認が必要です。適切なのはどれですか。',['定めた基準による全数検査','任意の1個だけ検査','基準を設けない','口頭の約束に代える'],'第23項：検査方法は目的、リスク、試験の性質に応じて選びます。'],
  [24,'Vì sao tiêu chuẩn hóa giúp đào tạo nhân viên mới?',['Cách làm và điểm kiểm tra được ghi rõ để cùng thực hiện','Vì không cần giải thích gì nữa','Vì mọi tình huống đều giống nhau','Vì nhân viên không cần phản hồi'],0,'Mục 24: Tiêu chuẩn hóa làm rõ phương pháp và tiêu chí, giúp duy trì chất lượng ổn định.','標準化が新人教育に役立つ理由は何ですか。',['方法と確認点が明確になり、共通して実施できる','説明が全く不要になる','すべての状況が同じになる','新人の意見が不要になる'],'第24項：方法と確認点を共有し、安定した作業につなげます。'],
  [24,'Một tiêu chuẩn cũ không còn phù hợp sau khi thay thiết bị. Cách xử lý đúng là gì?',['Xem xét dữ liệu, sửa và phổ biến tiêu chuẩn mới','Tiếp tục dùng bản cũ mãi mãi','Mỗi người tự đặt quy tắc','Chỉ thay tên file'],0,'Mục 24: Tiêu chuẩn cần được xem xét và cập nhật khi điều kiện thay đổi.','設備を変更したため、以前の標準が合わなくなりました。どうしますか。',['データを確認して改訂し、新標準を周知する','古い標準を永久に使う','各自で別のルールを決める','ファイル名だけ変える'],'第24項：条件が変われば標準を見直し、改訂内容を共有します。'],
  [25,'Tài liệu nêu thứ tự thao tác và điểm kiểm tra của nhân viên. Đây gần với loại nào?',['Tiêu chuẩn nghiệp vụ','Tiêu chuẩn hàng hóa về kích thước','Hợp đồng bán hàng','Bảng giá'],0,'Mục 25: Tiêu chuẩn nghiệp vụ quy định cách thực hiện công việc.','作業順序と作業者の確認点を定めた文書は何に近いですか。',['作業標準','製品寸法の規格','売買契約','価格表'],'第25項：作業標準は仕事の進め方を定めます。'],
  [25,'Bản vẽ quy định kích thước và vật liệu thành phẩm. Đây gần với loại nào?',['Tiêu chuẩn hàng hóa/sản phẩm','Tiêu chuẩn giờ nghỉ','Biên bản họp','Kế hoạch trực ca'],0,'Mục 25: Tiêu chuẩn sản phẩm mô tả yêu cầu đối với đầu ra cần tạo ra.','完成品の寸法と材料を規定した図面は何に近いですか。',['製品規格','休憩時間の規則','会議の議事録','勤務表'],'第25項：製品規格は出来上がりに求める条件を示します。'],
  [26,'JIS là ký hiệu thường dùng cho hệ tiêu chuẩn nào?',['Tiêu chuẩn công nghiệp Nhật Bản','Tiêu chuẩn nội bộ của một ca làm việc','Chỉ tiêu của một lô','Bản vẽ của một khách hàng'],0,'Mục 26: JIS là hệ tiêu chuẩn của Nhật Bản, khác với các chuẩn quốc tế như ISO.','JISは一般にどの標準を表しますか。',['日本産業規格','一つの勤務シフトの社内規則','一つのロットの指標','一顧客の図面'],'第26項：JISは日本の規格で、ISOなどの国際規格とは区別します。'],
  [26,'ISO và IEC có phạm vi nào phù hợp nhất?',['Đều là tổ chức tiêu chuẩn quốc tế; IEC tập trung lĩnh vực điện và điện tử','Đều chỉ là quy tắc của một phân xưởng','ISO chỉ dùng cho một sản phẩm cụ thể','IEC là tên một phương pháp lấy mẫu'],0,'Mục 26: Tiêu chuẩn quốc tế tạo ngôn ngữ chung; IEC tập trung lĩnh vực kỹ thuật điện và điện tử.','ISOとIECの説明として適切なのはどれですか。',['どちらも国際標準化に関わり、IECは電気・電子分野を中心とする','どちらも一工場だけの規則','ISOは一製品だけに使う','IECは抜取方法の名前'],'第26項：国際規格のうち、IECは電気・電子分野を中心に扱います。']
];
